import { readFileSync } from 'fs';
import { join } from 'path';

export interface PlatformInfo {
  platform: string;
  prettyName: string;
  shell: string;
}

let cached: PlatformInfo | null = null;

/**
 * Get platform metadata injected at build time.
 *
 * In production builds, electron-builder copies `resources/platform-config.json`
 * (generated by the build scripts from `TARGET_PLATFORM` env vars) into the
 * app's resources directory. In development we fall back to the project root
 * and finally to `process.platform` if no injected config exists.
 */
export function getPlatformInfo(): PlatformInfo {
  if (cached) return cached;

  const candidates = [
    // Production: resources dir inside the packaged app
    join(process.resourcesPath || '', 'platform-config.json'),
    // Development from dist-electron/main: ../../resources/platform-config.json
    join(__dirname, '..', '..', 'resources', 'platform-config.json'),
    // Development from source: ../../../resources/platform-config.json
    join(__dirname, '..', '..', '..', 'resources', 'platform-config.json'),
  ];

  for (const candidate of candidates) {
    try {
      const config = JSON.parse(readFileSync(candidate, 'utf-8')) as PlatformInfo;
      if (config.platform && config.prettyName && config.shell) {
        cached = config;
        return cached;
      }
    } catch {
      // Try next candidate
    }
  }

  // Fallback to runtime detection (development or missing injected config)
  const p = process.platform;
  cached = {
    platform: p,
    prettyName: p === 'win32' ? 'windows' : p === 'darwin' ? 'macos' : 'linux',
    shell: p === 'win32' ? process.env.COMSPEC || 'cmd.exe' : process.env.SHELL || '/bin/bash',
  };
  return cached;
}

/**
 * Clear the cached platform info. Useful for tests.
 */
export function clearPlatformInfoCache(): void {
  cached = null;
}